import Link from "next/link";import type {Vehicle} from "@/lib/types";
const money=(value:string)=>new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(Number(value));
export function VehicleCard({vehicle,index=0,editorial=false}:{vehicle:Vehicle;index?:number;editorial?:boolean}){return <article className={`vehicleCard ${editorial?"editorial":""}`} style={{"--delay":`${Math.min(index,6)*60}ms`} as React.CSSProperties}><Link href={`/vehicles/${vehicle.slug}`}><div className="cardImage">{vehicle.images[0]?<img src={vehicle.images[0].url} alt={vehicle.images[0].alt_text}/>:<div className="placeholder">{vehicle.make[0]}</div>}<div className="imageShade"/><span className={`status ${vehicle.availability}`}>{vehicle.availability}</span><span className="cardArrow" aria-hidden="true">↗</span></div><div className="cardCopy"><div><span className="vehicleMeta">{vehicle.year} · {vehicle.transmission} · {vehicle.mileage_km.toLocaleString()} km</span><h3>{vehicle.make} <span className="accentWord">{vehicle.model}</span></h3></div><strong>{money(vehicle.price)}</strong></div></Link></article>}
